CREATE COLUMN TABLE "TEST_AP"."ODNF" ("AbsEntry" INTEGER CS_INT NOT NULL , "NCMEntry" INTEGER CS_INT NOT NULL , "DNFCode" NVARCHAR(5) NOT NULL , "DNFUoM" NVARCHAR(10), "DNFFactor" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODNF_NCM_DNF" ON "TEST_AP"."ODNF" ( "NCMEntry" ASC, "DNFCode" ASC )